    return len(s) - max(dp)

#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperationsToSort(std::string s) {
        std::vector<int> dp(26, 0);
        for (char c : s) {
            int idx = c - 'a';
            int best = 0;
            for (int i = 0; i <= idx; ++i) best = std::max(best, dp[i]);
            dp[idx] = best + 1;
        }
        int maxL = 0;
        for (int v : dp) maxL = std::max(maxL, v);
        return s.length() - maxL;
    }
};

class Solution {
    public int minOperationsToSort(String s) {
        int[] dp = new int[26];
        for (char c : s.toCharArray()) {
            int idx = c - 'a';
            int best = 0;
            for (int i = 0; i <= idx; i++) best = Math.max(best, dp[i]);
            dp[idx] = best + 1;
        }
        int maxL = 0;
        for (int v : dp) maxL = Math.max(maxL, v);
        return s.length() - maxL;
    }
}

function minOperationsToSort(s) {
    const dp = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - 97;
        let best = 0;
        for (let j = 0; j <= idx; j++) best = Math.max(best, dp[j]);
        dp[idx] = best + 1;
    }
    return s.length - Math.max(...dp);
}
